import { Table, StringColumn, IntegerColumn, ReferenceColumn } from '@servicenow/sdk/core'

export const sn_table_app_incoming = Table({
    attributes: {
        other: true,
    },
    display: 'integer_column',
    extends: 'cmdb',
    index: [
        {
            name: 'index',
            unique: false,
            element: 'string_column',
        },
    ],
    label: 'Incoming Table',
    name: 'sn_table_app_incoming',
    schema: {
        string_column: StringColumn({
            attributes: {
                update_sync: false,
            },
            choices: {
                choice1: {
                    label: 'choice1',
                },
                choice2: {
                    label: 'choice2',
                },
            },
        }),
        integer_column: IntegerColumn({
            audit: true,
            choices: {
                1: {
                    label: 'One',
                    dependentValue: 'decide_strategy',
                },
                2: {
                    label: 'Two',
                    dependentValue: 1,
                },
            },
            dropdown: 'suggestion',
            label: 'Integer Column',
        }),
        reference_column: ReferenceColumn({
            referenceTable: 'task',
        }),
    },
})
